export const CHAOS_WEAVER_V2_DEF = {grid:CHAOS_WEAVER_V2_GRID,materials:CHAOS_WEAVER_V2_MATERIALS,parts:PARTS,
 animate({pose='idle',frame=0,now=0,progress=0,reducedMotion=false,attacking=false,charging=false,hurt=false,swapping=false}={}) {
  if (pose==='dead') return {partStates:{hideParts:true},effects:[]};
  const p=Math.max(0,Math.min(1,Number.isFinite(progress)?progress:0));
  const kind=reducedMotion?'idle':(swapping||pose==='swap')?'swap':(attacking||pose==='attack')?'attack':(charging||pose==='charge')?'charge':(hurt||pose==='hurt')?'hurt':'idle';
  const seq=POSES[kind]; const t=Math.floor(now>0?now/100:frame);
  const i=reducedMotion?0:kind==='idle'?((t%seq.length)+seq.length)%seq.length:Math.min(seq.length-1,Math.floor(p*seq.length));
  return {partStates:Object.fromEntries(Object.entries(seq[i]).map(([key,frame])=>[key,{frame}])),effects:[]};
 }};
